/**
 * Geography from the bundled GeoNames dataset (build plan §7.1): ZIP lookup, haversine distance,
 * the state list and counties by state. Data files are generated by scripts/build-zip-data.ts.
 */
import { classifyMove, isStateCode, parseZip5, type MoveType, type ResolvedLocation, type StateCode } from "@amc/core";
import countiesData from "../../data/counties.json";
import zipData from "../../data/zip5.json";
import { STATES, type StateInfo } from "./states";

type ZipTuple = [city: string, state: string, countyFips: string, lat: number, lng: number];

// The JSON imports are typed loosely on purpose: the compiler does not need 41,000 literal keys.
const ZIPS = zipData as unknown as Record<string, ZipTuple | undefined>;
const COUNTIES = countiesData as unknown as Record<string, [name: string, state: string] | undefined>;

export interface LatLng {
  lat: number;
  lng: number;
}

export interface ZipLocation extends ResolvedLocation, LatLng {
  countyName: string | null;
}

/**
 * Resolves a ZIP code ("02108", " 02108", "02108-1234") to its city, state, primary county and
 * centroid. Null for malformed or unknown codes and for ZIPs outside the 50 states and DC.
 */
export function lookupZip(input: string): ZipLocation | null {
  const zip = parseZip5(input);
  if (!zip) return null;
  const row = ZIPS[zip];
  if (!row) return null;
  const [city, state, countyFips, lat, lng] = row;
  if (!isStateCode(state)) return null;
  return { zip, city, state, countyFips, lat, lng, countyName: COUNTIES[countyFips]?.[0] ?? null };
}

const EARTH_RADIUS_MILES = 3958.8;

/** Great-circle (haversine) distance in miles. */
export function distanceMiles(a: LatLng, b: LatLng): number {
  const rad = Math.PI / 180;
  const dLat = (b.lat - a.lat) * rad;
  const dLng = (b.lng - a.lng) * rad;
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * rad) * Math.cos(b.lat * rad) * Math.sin(dLng / 2) ** 2;
  return 2 * EARTH_RADIUS_MILES * Math.asin(Math.min(1, Math.sqrt(h)));
}

/** Distance between two ZIP centroids in miles (one decimal), or null if either is unknown. */
export function zipDistanceMiles(from: string, to: string): number | null {
  const a = lookupZip(from);
  const b = lookupZip(to);
  if (!a || !b) return null;
  return Math.round(distanceMiles(a, b) * 10) / 10;
}

export interface ResolvedMove {
  origin: ZipLocation;
  destination: ZipLocation;
  distanceMiles: number;
  moveType: MoveType;
}

/** Both ends of a move, the distance and the move type (@amc/core classifyMove with local_max_miles). */
export function resolveMove(fromZip: string, toZip: string, localMaxMiles: number): ResolvedMove | null {
  const origin = lookupZip(fromZip);
  const destination = lookupZip(toZip);
  if (!origin || !destination) return null;
  const miles = Math.round(distanceMiles(origin, destination) * 10) / 10;
  return { origin, destination, distanceMiles: miles, moveType: classifyMove(origin, destination, miles, localMaxMiles) };
}

/** The 50 states and DC, alphabetical by name. */
export function statesList(): readonly StateInfo[] {
  return STATES;
}

export function stateByCode(code: string): StateInfo | null {
  return STATES.find((s) => s.code === code.toUpperCase()) ?? null;
}

export function stateBySlug(slug: string): StateInfo | null {
  return STATES.find((s) => s.slug === slug.toLowerCase()) ?? null;
}

export interface County {
  fips: string;
  name: string;
  state: StateCode;
}

let countiesByStateIndex: Map<string, County[]> | undefined;

/** Counties of one state (5-digit FIPS and name), alphabetical by name. Empty for unknown states. */
export function countiesByState(stateCode: string): County[] {
  if (!countiesByStateIndex) {
    countiesByStateIndex = new Map();
    for (const [fips, entry] of Object.entries(COUNTIES)) {
      if (!entry || !isStateCode(entry[1])) continue;
      const list = countiesByStateIndex.get(entry[1]) ?? [];
      list.push({ fips, name: entry[0], state: entry[1] });
      countiesByStateIndex.set(entry[1], list);
    }
    for (const list of countiesByStateIndex.values()) list.sort((a, b) => a.name.localeCompare(b.name));
  }
  return [...(countiesByStateIndex.get(stateCode.toUpperCase()) ?? [])];
}

/** One county by 5-digit FIPS code. */
export function countyByFips(fips: string): County | null {
  const entry = COUNTIES[fips];
  if (!entry || !isStateCode(entry[1])) return null;
  return { fips, name: entry[0], state: entry[1] };
}

/** Attribution required by the GeoNames licence (CC BY 4.0); the public footer shows it. */
export const GEONAMES_CREDIT = {
  text: "ZIP code data from GeoNames, licensed under CC BY 4.0",
  sourceUrl: "https://www.geonames.org/",
  licenseUrl: "https://creativecommons.org/licenses/by/4.0/",
} as const;
